import { Copy, Download, ShieldCheck } from "lucide-react";
import { notify } from "../../logic/notifications.js";
import { updateConfig, useViewerStore } from "../store.js";
import { Button, Field, Panel, Switch } from "../controls.jsx";
import { StatList } from "../StatList.jsx";

function downloadJson(filename, json) {
    const text = JSON.stringify(json, undefined, 4);
    const element = document.createElement("a");
    element.setAttribute("href", "data:application/json;charset=utf-8," + encodeURIComponent(text));
    element.setAttribute("download", filename);
    element.style.display = "none";
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
}

async function copyToClipboard(text) {
    try {
        await navigator.clipboard.writeText(text);
        notify("Copied to clipboard", "success");
        // eslint-disable-next-line no-unused-vars
    } catch (error) {
        notify("Error copying to clipboard.", "error");
    }
}

function severityMeta(severity) {
    switch (severity) {
        case 0:
            return { label: "Error", tone: "text-red-400", dot: "bg-red-400", badge: "bg-red-400" };
        case 1:
            return {
                label: "Warning",
                tone: "text-amber-400",
                dot: "bg-amber-400",
                badge: "bg-amber-400"
            };
        case 2:
            return { label: "Info", tone: "text-sky-300", dot: "bg-sky-300", badge: "bg-sky-300" };
        default:
            return { label: "Hint", tone: "text-ink/60", dot: "bg-ink/40", badge: "bg-ink/40" };
    }
}

// Warning codes the tab can optionally suppress, keyed by the toggle that hides them.
const IGNORABLE_CODES = {
    ignoreMissingTangents: "MESH_PRIMITIVE_GENERATED_TANGENT_SPACE",
    ignoreUnknownAttributes: "MESH_PRIMITIVE_INVALID_ATTRIBUTE",
    ignoreGlbVersion: "GLB_INVALID_VERSION"
};

// The messages the tab shows, given the current "ignore" toggles. The badge uses the
// same function so the header count and the list never disagree.
function visibleMessages(report, ignore) {
    return (report?.issues?.messages ?? []).filter(
        (message) =>
            !Object.entries(IGNORABLE_CODES).some(
                ([toggle, code]) => ignore[toggle] && message.code === code
            )
    );
}

export function ValidatorTab() {
    const report = useViewerStore((state) => state.published.validationReport);
    const ignoreMissingTangents = useViewerStore((state) => state.config.ignoreMissingTangents);
    const ignoreUnknownAttributes = useViewerStore((state) => state.config.ignoreUnknownAttributes);
    const ignoreGlbVersion = useViewerStore((state) => state.config.ignoreGlbVersion);

    const failed = report?.error !== undefined;
    const reportName = report?.uri?.substring(report.uri.lastIndexOf("/") + 1);
    const messages = visibleMessages(report, {
        ignoreMissingTangents,
        ignoreUnknownAttributes,
        ignoreGlbVersion
    });
    // Derive the summary counts from the same list the messages are rendered from.
    const countOf = (severity) =>
        messages.filter((message) => message.severity === severity).length;

    return (
        <Panel title="Validation">
            {!failed && (
                <div className="my-6">
                    <StatList
                        data={{
                            Errors: countOf(0),
                            Warnings: countOf(1),
                            Infos: countOf(2)
                        }}
                    />
                </div>
            )}

            {failed && <p className="my-2.5 text-red-400">{report.error}</p>}

            <Field label="Ignore">
                <Switch
                    checked={ignoreMissingTangents}
                    onChange={(checked) => updateConfig({ ignoreMissingTangents: checked })}
                    title="Missing tangents are generated at runtime with MikkTSpace, which may produce inconsistent tangents across renderers."
                >
                    Missing tangents
                </Switch>
                <Switch
                    checked={ignoreUnknownAttributes}
                    onChange={(checked) => updateConfig({ ignoreUnknownAttributes: checked })}
                    title="Unknown vertex attributes, such as those added by extensions like gaussian splats, are ignored."
                >
                    Unknown attributes
                </Switch>
                <Switch
                    checked={ignoreGlbVersion}
                    onChange={(checked) => updateConfig({ ignoreGlbVersion: checked })}
                    title="glTF 2.1's GLB version 3 container is flagged as invalid by the glTF 2.0 validator."
                >
                    Unknown GLB container format
                </Switch>
            </Field>

            {messages.length > 0 && (
                <ul className="my-4 space-y-2">
                    {messages.map((message, index) => {
                        const severity = severityMeta(message.severity);
                        return (
                            <li
                                key={index}
                                className="border-ink/10 min-w-0 rounded-md border px-3 py-2"
                            >
                                <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs">
                                    <span
                                        className={`flex items-center gap-1 font-medium ${severity.tone}`}
                                    >
                                        <span className={`size-1.5 rounded-full ${severity.dot}`} />
                                        {severity.label}
                                    </span>
                                    {message.code !== undefined && (
                                        <span className="text-ink/50 font-mono break-all">
                                            {message.code}
                                        </span>
                                    )}
                                </div>
                                <p className="mt-1 text-sm break-words">{message.message}</p>
                            </li>
                        );
                    })}
                </ul>
            )}

            {!failed && (
                <div className="flex shrink-0 flex-col items-start gap-3 my-6">
                    <Button onClick={() => copyToClipboard(JSON.stringify(report, undefined, 4))}>
                        <Copy size={16} aria-hidden="true" />
                        Copy
                    </Button>
                    <Button onClick={() => downloadJson(`${reportName}.report.json`, report)}>
                        <Download size={16} aria-hidden="true" />
                        Download
                    </Button>
                </div>
            )}

            <span className="text-ink/70 mt-6 text-sm">
                Powered by{" "}
                <a
                    href="https://github.com/KhronosGroup/glTF-Validator"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="underline"
                >
                    glTF-Validator
                </a>
            </span>
        </Panel>
    );
}

/**
 * Badge shown on the Validator tab header.
 */
export function ValidationCounter() {
    const report = useViewerStore((state) => state.published.validationReport);
    const ignoreMissingTangents = useViewerStore((state) => state.config.ignoreMissingTangents);
    const ignoreUnknownAttributes = useViewerStore((state) => state.config.ignoreUnknownAttributes);
    const ignoreGlbVersion = useViewerStore((state) => state.config.ignoreGlbVersion);
    const messages = visibleMessages(report, {
        ignoreMissingTangents,
        ignoreUnknownAttributes,
        ignoreGlbVersion
    });

    let info = "";
    let severity;

    if (report?.error) {
        info = "X";
        severity = 0;
    } else {
        const counts = { 0: 0, 1: 0, 2: 0 };
        for (const message of messages) {
            if (message.severity <= 2) {
                counts[message.severity]++;
            }
        }
        if (counts[0] > 0) {
            info = `${counts[0]}`;
            severity = 0;
        } else if (counts[1] > 0) {
            info = `${counts[1]}`;
            severity = 1;
        } else if (counts[2] > 0) {
            info = `${counts[2]}`;
            severity = 2;
        }
    }

    if (info.length > 3) {
        info = "999+";
    }

    const tone = severity !== undefined ? severityMeta(severity).badge : "";

    return (
        <span className="relative inline-flex">
            <ShieldCheck size={26} strokeWidth={1.75} aria-hidden="true" />
            {info !== "" && (
                <span
                    className={`absolute -top-2 -right-4 flex aspect-square min-w-6 items-center justify-center rounded-full text-sm font-bold text-black ${tone}`}
                >
                    {info}
                </span>
            )}
        </span>
    );
}
